CREATE TABLE public.ai_access_state(owner_id uuid PRIMARY KEY DEFAULT auth.uid(), blocked boolean NOT NULL DEFAULT false, status integer, message text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.ai_access_state TO authenticated; GRANT ALL ON public.ai_access_state TO service_role; ALTER TABLE public.ai_access_state ENABLE ROW LEVEL SECURITY; CREATE POLICY own_ai_state ON public.ai_access_state FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.call_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), organization_id uuid NOT NULL DEFAULT public.crm_org() REFERENCES public.organizations(id), lead_id uuid NOT NULL REFERENCES public.leads(id), request_id uuid NOT NULL UNIQUE, provider_sid text UNIQUE, status text NOT NULL DEFAULT 'queued', from_number text NOT NULL, rep_number text NOT NULL, to_number text NOT NULL, recording_consent boolean NOT NULL DEFAULT false, recording_sid text, recording_path text, duration integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.call_logs TO authenticated; GRANT ALL ON public.call_logs TO service_role; ALTER TABLE public.call_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY own_call_logs ON public.call_logs FOR ALL TO authenticated USING(owner_id=auth.uid() AND organization_id=public.crm_org()) WITH CHECK(owner_id=auth.uid() AND organization_id=public.crm_org() AND EXISTS(SELECT 1 FROM public.leads WHERE id=lead_id AND owner_id=auth.uid()));
CREATE POLICY read_own_recordings ON storage.objects FOR SELECT TO authenticated USING(bucket_id='call-recordings' AND (storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY insert_own_recordings ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='call-recordings' AND (storage.foldername(name))[1]=auth.uid()::text);